"""Printed 279–282: translation/rotation derivations, native axis diagrams."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
def axes(n):
 origin=(150,320);s=50;h,k=(1.7,1) if n in [33,35] else (0,0);ang=math.radians(35) if n in [34,35] else 0
 def old(x,y):return(origin[0]+s*x,origin[1]-s*y)
 def new(X,Y):return old(h+X*math.cos(ang)-Y*math.sin(ang),k+X*math.sin(ang)+Y*math.cos(ang))
 paths=[path([old(0,0),old(7,0)]),path([old(0,0),old(0,5.7)])];labels=[(503,327,'x'),(147,26,'y'),(132,342,'O')]
 if n==35:
  paths.extend([path([old(h,k),old(7,k)]),path([old(h,k),old(h,5.7)])]);labels.extend([(503,old(0,k)[1]+7,'x₁'),(old(h,0)[0],26,'y₁')])
 paths.extend([path([new(0,0),new(5.6,0)]),path([new(0,0),new(0,3.4)])]);labels.extend([(*new(5.8,0),'X' if n!=35 else 'X′'),(*new(0,3.6),'Y' if n!=35 else 'Y′')])
 X,Y=3.3,1.3;px,py=new(X,Y);ox,oy=new(0,0);nx,ny=new(X,0)
 paths.extend([path([(px,py),(nx,ny)],dash=True),path([(px,py),(px,origin[1])],dash=True)])
 labels.extend([(px+5,py-9,'P'),(nx+4,ny+21,'N' if n==34 else 'N₂'),(px-4,origin[1]+23,'M'),(ox-15,oy+22,'O′' if n==35 else 'O' if n==34 else 'O₁')])
 if n in [33,35]:
  paths.extend([path([old(0,0),old(h,0)],dash=True),path([old(h,0),old(h,k)],dash=True)]);labels.extend([(origin[0]+s*h/2,origin[1]+24,'h'),(ox+9,origin[1]-s*k/2,'k')])
 if n in [34,35]:labels.append((ox+35,oy-11,'θ'))
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — '+{33:'parallel translated axes',34:'counterclockwise rotated axes',35:'translated and counterclockwise rotated axes'}[n]+' with perpendicular point projections',paths,labels,points=[{'x':px,'y':py},{'x':ox,'y':oy}],size=(560,375))
PAGES=[page('144_page_1.jpg',279,[heading('9.4 Translation and Rotation of Axes'),paragraph('If coordinates of a point or equation of a curve are given with reference to a system of axes, rectangular or oblique, coordinates of the same point or equation of the same curve can be obtained with reference to another system. The process of changing coordinates is called the transformation of coordinates.'),heading('(i) Translation and rotation of axes'),paragraph('There are three types of change of axes: (a) Translation of Axes changes the origin only; the new axes are parallel to the old ones. (b) Rotation of Axes changes the directions without changing the origin. (c) General Transformation changes direction and origin together. The relationships between the two coordinate systems are called translation or rotation of axes respectively.'),heading('(ii) Equations of transformation for translation of axes'),paragraph('Let O(0,0) be the old origin of rectangular axes ox,oy, with old point coordinates P(x,y). Let O(h,k) be the new origin of parallel rectangular axes OX,OY, with new point coordinates P(X,Y). PM and ON are perpendicular to old axis ox; PM meets new OX at M₁. The assumptions are ON=h,NO₁=k,OM=x,MP=y,OM₁=X,M₁P=Y.'),axes(33),paragraph('Through old rectangular axes:'),eq(r'x=OM=ON+NM=ON+OM_1=h+X'),eq(r'y=MP=MM_1+M_1P=NO+M_1P=k+Y'),paragraph('Old coordinates x,y in terms of X,Y are:'),eq(r'x=X+h,\quad y=Y+k','97'),paragraph('Equations (97) are the transformation for translation. Substituting them in a given equation obtains a new equation of the same graph referred to the translated axes.'),heading('(iii) Equations of transformation for rotation of axes'),paragraph('New rectangular axes OX,OY are obtained by rotating old axes ox,oy through angle θ, 0<θ<90°, in the anti-clockwise direction.'),note('This is a change of coordinates for the same geometric points and curve. The formulas remain valid for any real rotation angle; the acute-angle restriction is used for the source projection diagram. In the native diagrams, numerical placement illustrates the source symbolic h,k,θ labels.')]),
page('144_page_2.jpg',280,[paragraph('If P has old coordinates (x,y), its new coordinates are (X,Y). If PM and PN are perpendicular to Ox and OX, and NN₁ and NM₁ are perpendicular to Ox and PM, then OM=x,MP=y,ON=X,NP=Y,∠M₁PN=θ. Through the old axes:'),eq(r'x=OM=ON_1-MN_1=ON_1-M_1N=ON\cos\theta-NP\sin\theta=X\cos\theta-Y\sin\theta'),eq(r'y=MP=MM_1+M_1P=N_1N+M_1P=ON\sin\theta+NP\cos\theta=X\sin\theta+Y\cos\theta'),axes(34),paragraph('The old coordinates in terms of new coordinates satisfy:'),eq(r'x=X\cos\theta-Y\sin\theta,\quad y=X\sin\theta+Y\cos\theta','98'),paragraph('An equivalent form is:'),eq(r'X=x\cos\theta+y\sin\theta,\quad Y=-x\sin\theta+y\cos\theta','99'),heading('(iv) Transformed equations through translation and rotation of axes'),heading('Example 28'),paragraph('Translate to parallel axes through (1,−2) the conic 4x²+25y²−8x+100y+4=0.'),heading('Solution'),paragraph('Substitute x=X+h=X+1 (h=1), y=Y+k=Y−2 (k=−2) in the given equation:'),eq(r'4(X+1)^2+25(Y-2)^2-8(X+1)+100(Y-2)+4=0'),paragraph('Completing square gives the standard ellipse in the XY-plane:'),eq(r'\frac{Y^2}{25}+\frac{Y^2}{4}=1','100'),paragraph('The standard form in the xy-plane is obtained by backward substitution X=x+1 and Y=y−2:'),eq(r'\frac{(x-1)^2}{25}+\frac{(y+2)^2}{4}=1,\quad X=x-1,\quad Y=y+2'),heading('Example 29'),paragraph('Transform to axes inclined 45° to the original axes the conic x²+y²−8x+4xy−1=0.'),heading('Solution'),paragraph('Use equation (98):'),eq(r'x=X\cos\theta-Y\sin\theta,\quad\theta=45^\circ'),eq(r'x=X\cos45^\circ-Y\sin45^\circ=\frac{\sqrt2}{2}X-\frac{\sqrt2}{2}Y=\frac{\sqrt2}{2}(X-Y)'),eq(r'y=X\sin\theta+Y\cos\theta=X\cos45^\circ+Y\sin45^\circ=\frac{\sqrt2}{2}(X+Y)'),eq(r'\frac24(X-Y)^2+\frac24(X+Y)^2-8\frac{\sqrt2}{2}(X-Y)+4\left(\frac24\right)(X-Y)(X+Y)-1=0'),note('Example 28 source equation (100) repeats Y²; the correct equation is X²/25+Y²/4=1. Its preceding backward-substitution sentence reverses both translation signs; correct inverse coordinates are X=x−1,Y=y+2, as the final displayed equation states. In Example 29 the swapped sine/cosine names at 45° have equal values, so the numerical rotation remains correct.')]),
page('145_page_1.jpg',281,[paragraph('To obtain the transformed equation of hyperbola:'),eq(r'3X^2-Y^2-4\sqrt2(X-Y)-1=0'),paragraph('The given conic is recovered by substituting:'),eq(r'X+Y=\frac{2y}{\sqrt2},\quad X-Y=\frac{2x}{\sqrt2}\quad\Rightarrow\quad X=\frac{x+y}{\sqrt2},\quad Y=\frac{x-y}{\sqrt2}'),heading('(v) New origin and new axes with respect to old origin and old axes'),paragraph('This is the general transformation requiring both translation and rotation. Let O(0,0) be the old origin of rectangular axes ox,oy, and the parallel translated axes OX,OY have origin O(h,k). New axes OX′,OY′ are obtained by rotating OX,OY through angle θ,0<θ<90°, in the anti-clockwise direction. Point P has coordinates P(x,y),P(X,Y),P(X′,Y′) in these systems respectively.'),paragraph('The assumptions are OM=x,MP=y,OM₁=X,M₁P=Y,ON₂=X′,N₂P=Y′. Through old axes:'),eq(r'x=OM=ON-MN=OL+LN-MN=OL+ON_1-M_2N_2'),eq(r'x=OL+ON_2\cos\theta-N_2P\sin\theta=h+X′\cos\theta-Y′\sin\theta'),eq(r'y=MP=MM_1+M_1M_2+M_2P=OL+N_1N_2+M_2P'),eq(r'y=k+ON_2\sin\theta+N_2P\cos\theta=k+X′\sin\theta+Y′\cos\theta'),axes(35),paragraph('Coordinates x,y in terms of X′,Y′ satisfy:'),eq(r'x=h+X′\cos\theta-Y′\sin\theta,\quad y=k+X′\sin\theta+Y′\cos\theta','101'),heading('Example 30'),paragraph('Transform to new axes inclined 45° to the original axes the conic x²+y²−8x+4xy−1=0 through (2,3).'),note('The inverse Y in Example 29 has the wrong sign: equations (98),(99) give Y=(y−x)/√2. The two preceding sum/difference relations also imply this corrected sign. General inverse coordinates are X′=(x−h)cosθ+(y−k)sinθ, Y′=−(x−h)sinθ+(y−k)cosθ. Use the coordinate relations to interpret the source’s repeated O labels in the projection diagrams.')]),
page('145_page_2.jpg',282,[heading('Solution'),paragraph('Use equation (101):'),eq(r'x=h+X′\cos\theta-Y′\sin\theta,\quad\theta=45^\circ'),eq(r'x=2+\frac{\sqrt2}{2}X′-\frac{\sqrt2}{2}Y′=2+\frac{\sqrt2}{2}(X′-Y′)'),eq(r'y=k+X′\sin\theta+Y′\cos\theta=3+\frac{\sqrt2}{2}(X′+Y′)'),paragraph('In the given conic equation:'),eq(r'\left[2+\frac2{\sqrt2}(X′-Y′)\right]^2+\left[3+\frac2{\sqrt2}(X′+Y′)\right]^2-8\left[2+\frac{\sqrt2}{2}(X′-Y′)\right]+4\left[2+\frac{\sqrt2}{2}(X′-Y′)\right]\left[3+\frac{\sqrt2}{2}(X′+Y′)\right]-1=0'),paragraph('To obtain the transformed equation of hyperbola:'),eq(r'3X′^2-Y′^2+4\sqrt2(X′-Y′)+7\sqrt2(X′+Y′)+20=0'),paragraph('It yields the given conic by substituting:'),eq(r'x=2+\frac{\sqrt2}{2}(X′-Y′),\quad y=3+\frac{\sqrt2}{2}(X′+Y′)'),eq(r'X′=\frac{x-2}{\sqrt2}+\frac{y-3}{\sqrt2},\quad Y′=\frac{y-3}{\sqrt2}-\frac{x-2}{\sqrt2}'),heading('(vi) Angle through which axes be rotated about the origin so the product term xy is removed from the transformed equation'),paragraph('Substitute equations (98) into ax²+2hxy+by²:'),eq(r'ax^2+2hxy+by^2=a(X\cos\theta-Y\sin\theta)^2+2h(X\cos\theta-Y\sin\theta)(X\sin\theta+Y\cos\theta)+b(X\sin\theta+Y\cos\theta)^2'),eq(r'=(a\cos^2\theta+2h\sin\theta\cos\theta+b\sin^2\theta)X^2+\{-2(a-b)\sin\theta\cos\theta+2h(\cos^2\theta-\sin^2\theta)\}XY+(a\sin^2\theta-2h\sin\theta\cos\theta+b\cos^2\theta)Y^2'),paragraph('This has form a′X²+b′Y² if the coefficient of XY equals zero:'),eq(r'-2(a-b)\sin\theta\cos\theta+2h(\cos^2\theta-\sin^2\theta)=0'),eq(r'-(a-b)\sin2\theta+2h\cos2\theta=0'),eq(r'-(a-b)\sin2\theta=-2h\cos2\theta'),eq(r'\frac{\sin2\theta}{\cos2\theta}=\frac{2h}{a-b}\quad\Rightarrow\quad\tan2\theta=\frac{2h}{a-b}'),eq(r'\theta=\frac12\tan^{-1}\left(\frac{2h}{a-b}\right)','102'),heading('Example 31'),paragraph('At what angle are the axes rotated about the origin so the transformed conic 9x²+4y²+12xy−x−y=0 does not contain the term XY?'),note('Example 30’s substitution line incorrectly uses 2/√2 in the two squared brackets, instead of √2/2=1/√2; the preceding substitutions and following simplified equation are correct. In the rotation-removal formula, h denotes half the xy coefficient, unrelated to a translated-origin coordinate also called h. Use the division-free condition −(a−b)sin2θ+2hcos2θ=0 for special cases: if a=b and h≠0, θ=45° works; if a=b,h=0, every angle works. For a≠b, the arctangent solution is understood modulo 90°.')])]
for v in PAGES:v.update(title='CONICS-II',visualStatus='All projection-derived coordinate relations, three native axis diagrams and complete source rotation algebra',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(v['page']+9)//2,'side':'left' if v['page']%2 else 'right','reason':'All source coordinate signs checked; Example 30 squared-bracket coefficients enlarged and confirmed'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
('28','Translate 4x² + 25y² − 8x + 100y + 4 = 0 to parallel axes through (1, − 2).',['The new origin is (h,k) = (1, − 2); substitute x = X + 1,y = Y − 2.','The equation becomes 4(X + 1)² + 25(Y − 2)² − 8(X + 1) + 100(Y − 2) + 4 = 0.','Expand: X terms 4X² + 8X + 4 − 8X − 8 give 4X² − 4; Y terms 25Y² − 100Y + 100 + 100Y − 200 give 25Y² − 100.','Adding the remaining  + 4 yields 4X² + 25Y² − 100 = 0.','Divide by 100: X²/25 + Y²/4 = 1. The source repeats Y in the first term of equation (100), which is a typo.','Use X = x − 1,Y = y + 2 to recover (x − 1)²/25 + (y + 2)²/4 = 1; its center is the new origin.'],'X²/25 + Y²/4 = 1.',280,280),
('29','Rotate axes 45° for x² + y² − 8x + 4xy − 1 = 0.',['For counterclockwise axes rotation, substitute x = (X − Y)/√2,y = (X + Y)/√2.','Then x² + y² = X² + Y², and 4xy = 2(X² − Y²).','The linear term is  − 8x =  − 4√2(X − Y).','Combining gives 3X² − Y² − 4√2(X − Y) − 1 = 0, with no XY term.','The inverse coordinates are X = (x + y)/√2,Y = (y − x)/√2; the source reverses the sign of its final Y expression.','Substitute the correct inverse to recover the original equation. Opposite signs of the squared terms classify a nondegenerate hyperbola.'],'3X² − Y² − 4√2X + 4√2Y − 1 = 0.',280,281),
('30','Translate to origin (2,3) and rotate axes 45° for x² + y² − 8x + 4xy − 1 = 0.',['Use x = 2 + (X′ − Y′)/√2 and y = 3 + (X′ + Y′)/√2.','Before rotation, let u = x − 2,v = y − 3. Expansion gives u² + v² + 4uv + 8u + 14v + 20 = 0.','Substitute u = (X′ − Y′)/√2,v = (X′ + Y′)/√2; the squared part becomes 3X′² − Y′².','The linear part becomes 4√2(X′ − Y′) + 7√2(X′ + Y′).','Therefore 3X′² − Y′² + 11√2X′ + 3√2Y′ + 20 = 0. The source’s two squared substitution brackets have a factor-of-two typo, while its final simplified result agrees.','Invert with X′ = ((x − 2) + (y − 3))/√2 and Y′ = ((y − 3) − (x − 2))/√2; the new origin corresponds to (x,y) = (2,3).','Substituting this inverse recovers the original conic and confirms the translation/rotation signs.'],'3X′² − Y′² + 11√2X′ + 3√2Y′ + 20 = 0.',281,282)]:
 EXAMPLES.append({'num':n,'title':'Coordinate Transformation','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg + 9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'Complete source transformations and every coordinate sign checked'} for pg in range(start,end + 1)]})
